const { plugin_settings_hide_external_feedback: config } =
  await chrome.storage.local.get("plugin_settings_hide_external_feedback");

if (config?.enabled !== false) {
  function hide() {
    const xpath =
      "//p[text()='Task Feedback for Contributor (External)']/parent::*/parent::div";
    const result = document.evaluate(
      xpath,
      document,
      null,
      XPathResult.FIRST_ORDERED_NODE_TYPE,
      null,
    );
    const div = result.singleNodeValue;
    if (div) div.style.display = "none";
  }

  hide();
  new MutationObserver(hide).observe(document.body, {
    childList: true,
    subtree: true,
  });
}
